/* @lc app=leetcode id=2251 lang=kotlin */ class Solution { fun fullBloomFlowers(flowers: Array<IntArray>, people: IntArray): IntArray = flowers.map { it[0] }.sorted().let { s -> flowers.map { it[1] + 1 }.sorted().let { e -> people.map { p -> s.let { b -> generateSequence(0 to b.size) { (l, r) -> if (l >= r) null else ((l + r) / 2).let { m -> if (b[m] <= p) m + 1 to r else l to m } }.last().first } - e.let { b -> generateSequence(0 to b.size) { (l, r) -> if (l >= r) null else ((l + r) / 2).let { m -> if (b[m] <= p) m + 1 to r else l to m } }.last().first } }.toIntArray() } } }